13	
14		corev1 "k8s.io/api/core/v1"
15		metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
16		"k8s.io/client-go/kubernetes"
17		"k8s.io/client-go/rest"
18	
19		"github.com/vllm-project/semantic-router/e2e/pkg/cluster"
20		"github.com/vllm-project/semantic-router/e2e/pkg/docker"
21		"github.com/vllm-project/semantic-router/e2e/pkg/testcases"
22	)
23	
24	// Runner orchestrates the E2E test execution
25	type Runner struct {
26		opts                *TestOptions
27		profile             Profile
28		profileCapabilities ProfileCapabilities
29		cluster             *cluster.KindCluster
30		builder             *docker.Builder
31		restConfig          *rest.Config
32		reporter            *ReportGenerator
33	}
34	
35	// NewRunner creates a new test runner
36	func NewRunner(opts *TestOptions, profile Profile) *Runner {
37		capabilities := ProfileCapabilities{}
38		if reg, ok := LookupProfileRegistration(profile.Name()); ok {
39			capabilities = reg.Capabilities
40		}
41	
42		return &Runner{
43			opts:                opts,
44			profile:             profile,
45			profileCapabilities: capabilities,
46			cluster:             cluster.NewKindCluster(opts.ClusterName, opts.Verbose),
47			builder:             docker.NewBuilder(opts.Verbose),
48		}
49	}
50	
51	func (r *Runner) setupCluster(ctx context.Context) error {
52		r.log("Setting up Kind cluster: %s", r.opts.ClusterName)
53	
54		if r.profileCapabilities.RequiresGPU {
55			r.log("Enabling GPU support for profile %s", r.profile.Name())
56			r.cluster.SetGPUEnabled(true)
57		}
58	
59		if r.opts.UseWorkspaceModels {
60			workspaceModelsDir, err := resolveWorkspaceModelsDir()
61			if err != nil {
62				return err
63			}
64			r.log("Using workspace models directory: %s", workspaceModelsDir)
65			r.cluster.SetWorkspaceModelsDir(workspaceModelsDir)
66		}
67	
68		return r.cluster.Create(ctx)
69	}
70	
71	func (r *Runner) cleanupCluster(ctx context.Context) {
72		r.log("Cleaning up Kind cluster: %s", r.opts.ClusterName)
73		if err := r.cluster.Delete(ctx); err != nil {
74			r.log("Warning: failed to delete cluster: %v", err)
75		}
76	}
77	
78	func (r *Runner) buildAndLoadImages(ctx context.Context) error {
79		r.log("Building and loading Docker images")
80	
81		buildOpts := docker.BuildOptions{
82			Dockerfile:   "tools/docker/Dockerfile.extproc",
83			Tag:          fmt.Sprintf("ghcr.io/vllm-project/semantic-router/extproc:%s", r.opts.ImageTag),
84			BuildContext: ".",
85			BuildArgs:    localDockerBuildArgs(),
86		}
87	
88		if err := r.builder.BuildAndLoad(ctx, r.opts.ClusterName, buildOpts); err != nil {
89			return err
90		}
91	
92		for _, image := range r.profileCapabilities.LocalImages {
93			buildOpts := docker.BuildOptions{
94				Dockerfile:   image.Dockerfile,
95				Tag:          image.Tag,
96				BuildContext: image.BuildContext,
97			}
98			if err := r.builder.BuildAndLoad(ctx, r.opts.ClusterName, buildOpts); err != nil {
99				return err
100			}
101		}
102	
103		return nil
104	}
105	
106	func (r *Runner) runTests(ctx context.Context, kubeClient *kubernetes.Clientset) ([]TestResult, error) {
107		r.log("Running tests")
108	
109		// Debug: List all registered test cases
110		if r.opts.Verbose {
111			r.log("All registered test cases:")
112			for _, tc := range testcases.List() {
113				r.log("  - %s: %s", tc.Name, tc.Description)
114			}
115		}
116	
117		// Get test cases to run
118		var testCasesToRun []testcases.TestCase
119		var err error
120	
121		if len(r.opts.TestCases) > 0 {
122			// Run specific test cases
