package framework

import (
	"context"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"sync"
	"time"

	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/rest"

	"github.com/vllm-project/semantic-router/e2e/pkg/cluster"
	"github.com/vllm-project/semantic-router/e2e/pkg/docker"
	"github.com/vllm-project/semantic-router/e2e/pkg/testcases"
)

// Runner orchestrates the E2E test execution
type Runner struct {
	opts                *TestOptions
	profile             Profile
	profileCapabilities ProfileCapabilities
	cluster             *cluster.KindCluster
	builder             *docker.Builder
	restConfig          *rest.Config
	reporter            *ReportGenerator
}

// NewRunner creates a new test runner
func NewRunner(opts *TestOptions, profile Profile) *Runner {
	capabilities := ProfileCapabilities{}
	if reg, ok := LookupProfileRegistration(profile.Name()); ok {
		capabilities = reg.Capabilities
	}

	return &Runner{
		opts:                opts,
		profile:             profile,
		profileCapabilities: capabilities,
		cluster:             cluster.NewKindCluster(opts.ClusterName, opts.Verbose),
		builder:             docker.NewBuilder(opts.Verbose),
	}
}

func (r *Runner) setupCluster(ctx context.Context) error {
	r.log("Setting up Kind cluster: %s", r.opts.ClusterName)

	if r.profileCapabilities.RequiresGPU {
		r.log("Enabling GPU support for profile %s", r.profile.Name())
		r.cluster.SetGPUEnabled(true)
	}

	if r.opts.UseWorkspaceModels {
		workspaceModelsDir, err := resolveWorkspaceModelsDir()
		if err != nil {
			return err
		}
		r.log("Using workspace models directory: %s", workspaceModelsDir)
		r.cluster.SetWorkspaceModelsDir(workspaceModelsDir)
	}

	return r.cluster.Create(ctx)
}

func (r *Runner) cleanupCluster(ctx context.Context) {
	r.log("Cleaning up Kind cluster: %s", r.opts.ClusterName)
	if err := r.cluster.Delete(ctx); err != nil {
		r.log("Warning: failed to delete cluster: %v", err)
	}
}

func (r *Runner) buildAndLoadImages(ctx context.Context) error {
	r.log("Building and loading Docker images")

	buildOpts := docker.BuildOptions{
		Dockerfile:   "tools/docker/Dockerfile.extproc",
		Tag:          fmt.Sprintf("ghcr.io/vllm-project/semantic-router/extproc:%s", r.opts.ImageTag),
		BuildContext: ".",
		BuildArgs:    localDockerBuildArgs(),
	}

	if err := r.builder.BuildAndLoad(ctx, r.opts.ClusterName, buildOpts); err != nil {
		return err
	}

	for _, image := range r.profileCapabilities.LocalImages {
		buildOpts := docker.BuildOptions{
			Dockerfile:   image.Dockerfile,
			Tag:          image.Tag,
			BuildContext: image.BuildContext,
		}
		if err := r.builder.BuildAndLoad(ctx, r.opts.ClusterName, buildOpts); err != nil {
			return err
		}
	}

	return nil
}

func (r *Runner) runTests(ctx context.Context, kubeClient *kubernetes.Clientset) ([]TestResult, error) {
	r.log("Running tests")

	// Debug: List all registered test cases
	if r.opts.Verbose {
		r.log("All registered test cases:")
		for _, tc := range testcases.List() {
			r.log("  - %s: %s", tc.Name, tc.Description)
		}
	}

	// Get test cases to run
	var testCasesToRun []testcases.TestCase
	var err error

	if len(r.opts.TestCases) > 0 {
		// Run specific test cases
		r.log("Requested test cases: %v", r.opts.TestCases)
		testCasesToRun, err = testcases.ListByNames(r.opts.TestCases...)
		if err != nil {
			return nil, err
		}
	} else {
		// Run all test cases for the profile
		profileTestCases := r.profile.GetTestCases()
		r.log("Profile test cases: %v", profileTestCases)
		testCasesToRun, err = testcases.ListByNames(profileTestCases...)
		if err != nil {
			return nil, err
		}
	}

	r.log("Running %d test cases", len(testCasesToRun))

	results := make([]TestResult, 0, len(testCasesToRun))
	resultsMu := sync.Mutex{}

	if r.opts.Parallel {
		// Run tests in parallel
		var wg sync.WaitGroup
		for _, tc := range testCasesToRun {
			wg.Add(1)
			go func(tc testcases.TestCase) {
				defer wg.Done()
				result := r.runSingleTest(ctx, kubeClient, tc)
				resultsMu.Lock()
				results = append(results, result)
				resultsMu.Unlock()
			}(tc)
		}
		wg.Wait()
	} else {
		// Run tests sequentially
		for _, tc := range testCasesToRun {
			result := r.runSingleTest(ctx, kubeClient, tc)
			results = append(results, result)
		}
	}

	return results, nil
}

func (r *Runner) runSingleTest(ctx context.Context, kubeClient *kubernetes.Clientset, tc testcases.TestCase) TestResult {
	r.log("Running test: %s", tc.Name)

	start := time.Now()

	// Get service configuration from profile
	svcConfig := r.profile.GetServiceConfig()

	// Create result to capture details
	result := TestResult{
		Name:    tc.Name,
		Details: make(map[string]interface{}),
	}

	opts := testcases.TestCaseOptions{
		Verbose:       r.opts.Verbose,
		Profile:       r.profile.Name(),
		Namespace:     "default",
		Timeout:       "5m",
		RestConfig:    r.restConfig,
		ServiceConfig: svcConfig,
		SetDetails: func(details map[string]interface{}) {
			result.Details = details
		},
	}

	err := tc.Fn(ctx, kubeClient, opts)
	duration := time.Since(start)

	result.Passed = err == nil
	result.Error = err
	result.Duration = duration.String()

	if err != nil {
		r.log("❌ Test %s failed: %v", tc.Name, err)
	} else {
		r.log("✅ Test %s passed (%s)", tc.Name, duration)
	}

	return result
}

func (r *Runner) printResults(results []TestResult) {
	fmt.Println("\n" + strings.Repeat("=", 80))
	fmt.Println("TEST RESULTS")
	fmt.Println(strings.Repeat("=", 80))

	passed := 0
	failed := 0

	for _, result := range results {
		status := "✅ PASSED"
		if !result.Passed {
			status = "❌ FAILED"
			failed++
		} else {
			passed++
		}

		fmt.Printf("%s - %s (%s)\n", status, result.Name, result.Duration)
		if result.Error != nil {
			fmt.Printf("  Error: %v\n", result.Error)
		}
	}

	fmt.Println(strings.Repeat("=", 80))
	fmt.Printf("Total: %d | Passed: %d | Failed: %d\n", len(results), passed, failed)
	fmt.Println(strings.Repeat("=", 80))
}

func (r *Runner) log(format string, args ...interface{}) {
	if r.opts.Verbose {
		fmt.Printf("[Runner] "+format+"\n", args...)
	}
}

func resolveWorkspaceModelsDir() (string, error) {
	workingDir, err := os.Getwd()
	if err != nil {
		return "", fmt.Errorf("resolve workspace models directory: %w", err)
	}

	modelsDir := filepath.Join(workingDir, "models")
	if err := os.MkdirAll(modelsDir, 0o755); err != nil {
		return "", fmt.Errorf("create workspace models directory %s: %w", modelsDir, err)
	}

	return modelsDir, nil
}

func localDockerBuildArgs() map[string]string {
	return map[string]string{
		"BUILDPLATFORM": "linux/" + runtime.GOARCH,
		"TARGETARCH":    runtime.GOARCH,
	}
}

func (r *Runner) printAllPodsDebugInfo(ctx context.Context, client *kubernetes.Clientset) {
	fmt.Printf("\n")
	fmt.Println(strings.Repeat("=", 80))
	fmt.Println("DEBUGGING INFORMATION - ALL PODS STATUS")
	fmt.Println(strings.Repeat("=", 80))

	// Get all pods from all namespaces
	pods, err := client.CoreV1().Pods("").List(ctx, metav1.ListOptions{})
	if err != nil {
		fmt.Printf("Failed to list pods: %v\n", err)
		return
	}

	fmt.Printf("\nTotal pods across all namespaces: %d\n", len(pods.Items))

	// Group pods by namespace
	podsByNamespace := make(map[string][]string)
	for _, pod := range pods.Items {
		status := fmt.Sprintf("%s (Phase: %s, Ready: %s)",
			pod.Name,
			pod.Status.Phase,
			getPodReadyStatus(pod))
		podsByNamespace[pod.Namespace] = append(podsByNamespace[pod.Namespace], status)
	}

	// Print summary by namespace
	fmt.Printf("\nPods by namespace:\n")
	for ns, podList := range podsByNamespace {
		fmt.Printf("\n  Namespace: %s (%d pods)\n", ns, len(podList))
		for _, podStatus := range podList {
			fmt.Printf("    - %s\n", podStatus)
		}
	}

	fmt.Printf("\n")
	fmt.Println(strings.Repeat("=", 80))
	fmt.Printf("\n")
}

// collectSemanticRouterLogs collects logs from semantic-router pods and saves to file
func (r *Runner) collectSemanticRouterLogs(ctx context.Context, client *kubernetes.Clientset) error {
	// Find semantic-router pods
	pods, err := client.CoreV1().Pods("vllm-semantic-router-system").List(ctx, metav1.ListOptions{})
	if err != nil {
		return fmt.Errorf("failed to list semantic-router pods: %w", err)
	}

	if len(pods.Items) == 0 {
		r.log("Warning: no semantic-router pods found")
		return nil
	}

	// Collect logs from all semantic-router pods
	var allLogs strings.Builder
	allLogs.WriteString("========================================\n")
	allLogs.WriteString("Semantic Router Logs\n")
	allLogs.WriteString("========================================\n\n")

	for _, pod := range pods.Items {
		r.appendPodLogs(ctx, client, &allLogs, pod)
	}

	// Write logs to file
	logFilename := "semantic-router-logs.txt"
	if err := os.WriteFile(logFilename, []byte(allLogs.String()), 0644); err != nil {
		return fmt.Errorf("failed to write log file: %w", err)
	}

	r.log("✅ Semantic router logs saved to: %s", logFilename)
	return nil
}

func (r *Runner) appendPodLogs(
	ctx context.Context,
	client *kubernetes.Clientset,
	allLogs *strings.Builder,
	pod corev1.Pod,
) {
	fmt.Fprintf(allLogs, "=== Pod: %s (Namespace: %s) ===\n", pod.Name, pod.Namespace)
	fmt.Fprintf(allLogs, "Status: %s\n", pod.Status.Phase)
	fmt.Fprintf(allLogs, "Node: %s\n", pod.Spec.NodeName)
	if pod.Status.StartTime != nil {
		fmt.Fprintf(allLogs, "Started: %s\n", pod.Status.StartTime.Format(time.RFC3339))
	}
	allLogs.WriteString("\n")

	for _, container := range pod.Spec.Containers {
		r.appendContainerLogs(ctx, client, allLogs, pod, container.Name)
	}

	allLogs.WriteString("\n")
}

func (r *Runner) appendContainerLogs(
	ctx context.Context,
	client *kubernetes.Clientset,
	allLogs *strings.Builder,
	pod corev1.Pod,
	containerName string,
) {
	fmt.Fprintf(allLogs, "--- Container: %s ---\n", containerName)

	logOptions := &corev1.PodLogOptions{Container: containerName}
	req := client.CoreV1().Pods(pod.Namespace).GetLogs(pod.Name, logOptions)
	logs, err := req.Stream(ctx)
	if err != nil {
		fmt.Fprintf(allLogs, "Error getting logs: %v\n\n", err)
		return
	}

	logBytes, readErr := io.ReadAll(logs)
	if closeErr := logs.Close(); closeErr != nil {
		r.log("Warning: failed to close log stream for %s/%s: %v", pod.Name, containerName, closeErr)
	}
	if readErr != nil {
		fmt.Fprintf(allLogs, "Error reading logs: %v\n\n", readErr)
		return
	}

	if len(logBytes) == 0 {
		allLogs.WriteString("(no logs available)\n\n")
		return
	}

	allLogs.Write(logBytes)
	allLogs.WriteString("\n\n")
}

func getPodReadyStatus(pod corev1.Pod) string {
	readyCount := 0
	totalCount := len(pod.Status.ContainerStatuses)
	for _, cs := range pod.Status.ContainerStatuses {
		if cs.Ready {
			readyCount++
		}
	}
	return fmt.Sprintf("%d/%d", readyCount, totalCount)
}

package framework

import (
	"context"

	"k8s.io/client-go/kubernetes"

	pkgtestcases "github.com/vllm-project/semantic-router/e2e/pkg/testcases"
)

// Profile defines the interface that all test profiles must implement
type Profile interface {
	// Name returns the profile name
	Name() string

	// Setup prepares the environment for testing (e.g., deploy Helm charts)
	Setup(ctx context.Context, opts *SetupOptions) error

	// Teardown cleans up resources created during setup
	Teardown(ctx context.Context, opts *TeardownOptions) error

	// GetTestCases returns the list of test cases to run for this profile
	GetTestCases() []string

	// GetServiceConfig returns the service configuration for accessing the deployed service
	GetServiceConfig() ServiceConfig
}

// ServiceConfig is the canonical service-connection contract shared by profiles and testcases.
type ServiceConfig = pkgtestcases.ServiceConfig

// SetupOptions contains options for profile setup
type SetupOptions struct {
	// KubeClient is the Kubernetes client
	KubeClient *kubernetes.Clientset

	// KubeConfig is the path to kubeconfig file
	KubeConfig string

	// ClusterName is the name of the Kind cluster
	ClusterName string

	// ImageTag is the Docker image tag to use
	ImageTag string

	// Verbose enables verbose logging
	Verbose bool

	// ValuesFiles contains paths to Helm values files
	// keyed by Helm release name for profile-specific overlays.
	ValuesFiles map[string]string
}

// TeardownOptions contains options for profile teardown
type TeardownOptions struct {
	// KubeClient is the Kubernetes client
	KubeClient *kubernetes.Clientset

	// KubeConfig is the path to kubeconfig file
	KubeConfig string

	// ClusterName is the name of the Kind cluster
	ClusterName string

	// Verbose enables verbose logging
	Verbose bool
}

// TestOptions contains options for running tests
type TestOptions struct {
	// Profile is the test profile to run
	Profile string

	// ClusterName is the name of the Kind cluster
	ClusterName string

	// ImageTag is the Docker image tag to use
	ImageTag string

	// KeepCluster preserves the kind cluster and profile resources after the run.
	KeepCluster bool

	// UseExistingCluster uses an existing cluster instead of creating a new one
	UseExistingCluster bool

	// Verbose enables verbose logging
	Verbose bool

	// Parallel runs tests in parallel
	Parallel bool

	// TestCases is a list of specific test cases to run (empty means all)
	TestCases []string

	// SetupOnly only sets up the profile without running tests
	SetupOnly bool

	// SkipSetup skips profile setup and only runs tests (assumes environment is already deployed)
	SkipSetup bool

	// UseWorkspaceModels mounts the workspace models/ directory into semantic-router.
	UseWorkspaceModels bool
}

// TestResult represents the result of a test case
type TestResult struct {
	// Name is the test case name
	Name string

	// Passed indicates if the test passed
	Passed bool

	// Error contains the error if the test failed
	Error error

	// Duration is how long the test took
	Duration string

	// Logs contains test output logs
	Logs string

	// Details contains structured test-specific details (e.g., accuracy, hit rate)
	Details map[string]interface{}
}

package testcases

import (
	"context"
	"fmt"
	"sync"

	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/rest"
)

// TestCase represents a single test case
type TestCase struct {
	// Name is the unique identifier for the test case
	Name string

	// Description describes what the test does
	Description string

	// Tags are optional tags for filtering tests
	Tags []string

	// Fn is the test function to execute
	Fn func(ctx context.Context, client *kubernetes.Clientset, opts TestCaseOptions) error
}

// TestCaseOptions contains options passed to test cases
type TestCaseOptions struct {
	// Verbose enables verbose logging
	Verbose bool

	// Profile is the active E2E profile name running this testcase.
	Profile string

	// Namespace is the Kubernetes namespace to use
	Namespace string

	// ServiceURL is the URL of the service to test
	ServiceURL string

	// Timeout is the test timeout duration
	Timeout string

	// RestConfig is the Kubernetes REST config
	RestConfig *rest.Config

	// ServiceConfig contains service-specific configuration
	ServiceConfig ServiceConfig

	// SetDetails allows test cases to set structured details for reporting
	// Example: opts.SetDetails(map[string]interface{}{"accuracy": 95.5, "total_tests": 100})
	SetDetails func(details map[string]interface{})
}

// ServiceConfig contains configuration for accessing a service
type ServiceConfig struct {
	// LabelSelector is the label selector to find the service
	// Example: "gateway.envoyproxy.io/owning-gateway-namespace=default,gateway.envoyproxy.io/owning-gateway-name=semantic-router"
	LabelSelector string

	// Namespace is the namespace where the service is located
	Namespace string

	// Name is the service name (optional, if not using label selector)
	Name string

	// ServicePort is the port exposed by the Kubernetes Service.
	ServicePort string

	// LocalPort is an optional fixed local port for port-forwarding.
	// Empty means the framework chooses an ephemeral local port.
	LocalPort string

	// PortMapping is a deprecated compatibility shim for older profiles.
	// The service-side port is still honored, but the local port is ignored unless LocalPort is set.
	PortMapping string
}

var (
	registry = make(map[string]TestCase)
	mu       sync.RWMutex
)

// Register registers a test case
func Register(name string, tc TestCase) {
	mu.Lock()
	defer mu.Unlock()

	if _, exists := registry[name]; exists {
		panic(fmt.Sprintf("test case %q already registered", name))
	}

	tc.Name = name
	tc.Fn = wrapWithAcceptanceContract(name, tc.Fn)
	registry[name] = tc
}

// Get retrieves a test case by name
func Get(name string) (TestCase, bool) {
	mu.RLock()
	defer mu.RUnlock()

	tc, ok := registry[name]
	return tc, ok
}

// List returns all registered test cases
func List() []TestCase {
	mu.RLock()
	defer mu.RUnlock()

	cases := make([]TestCase, 0, len(registry))
	for _, tc := range registry {
		cases = append(cases, tc)
	}
	return cases
}

// ListByNames returns test cases matching the given names
func ListByNames(names ...string) ([]TestCase, error) {
	mu.RLock()
	defer mu.RUnlock()

	cases := make([]TestCase, 0, len(names))
	for _, name := range names {
		tc, ok := registry[name]
		if !ok {
			return nil, fmt.Errorf("test case %q not found", name)
		}
		cases = append(cases, tc)
	}
	return cases, nil
}

