141	
142	func wrapWithAcceptanceContract(
143		name string,
144		fn func(ctx context.Context, client *kubernetes.Clientset, opts TestCaseOptions) error,
145	) func(ctx context.Context, client *kubernetes.Clientset, opts TestCaseOptions) error {
146		if !hasScopedAcceptanceContract(name) {
147			return fn
148		}
149	
150		return func(ctx context.Context, client *kubernetes.Clientset, opts TestCaseOptions) error {
151			contract, ok := acceptanceContractForProfile(opts.Profile, name)
152			if !ok {
153				return fn(ctx, client, opts)
154			}
155	
156			originalSetDetails := opts.SetDetails
157			var details map[string]interface{}
158	
159			opts.SetDetails = func(next map[string]interface{}) {
160				details = next
161			}
162	
163			err := fn(ctx, client, opts)
164			if contractErr := evaluateAcceptanceContract(name, contract, details); err == nil && contractErr != nil {
165				err = contractErr
166			}
167	
168			if originalSetDetails != nil && details != nil {
169				originalSetDetails(details)
170			}
171	
172			return err
173		}
174	}
175	
176	func hasScopedAcceptanceContract(name string) bool {
177		for _, contracts := range acceptanceContractsByProfile {
178			if _, ok := contracts[name]; ok {
179				return true
180			}
181		}
182	
183		return false
184	}
185	
186	func acceptanceContractForProfile(profile, name string) (acceptanceContract, bool) {
187		contracts, ok := acceptanceContractsByProfile[profile]
188		if !ok {
189			return nil, false
190		}
191	
192		contract, ok := contracts[name]
193		return contract, ok
194	}
195	
196	func evaluateAcceptanceContract(name string, contract acceptanceContract, details map[string]interface{}) error {
197		if details == nil {
198			return fmt.Errorf("%s did not publish structured details required for acceptance evaluation", name)
199		}
200	
201		if err := contract(details); err != nil {
202			return fmt.Errorf("%s failed acceptance contract: %w", name, err)
203		}
204	
205		return nil
206	}
207	
208	func applyFlatRateContract(spec flatRateContract) acceptanceContract {
209		return func(details map[string]interface{}) error {
210			rate, err := buildAcceptanceRate(details, spec.numeratorKey, spec.denominatorKey)
211			if err != nil {
212				return err
213			}
214	
215			rate.addDetails(details, spec.actualKey, spec.minimumKey, spec.minimum)
216			return rate.requireMinimum(spec.metricName, spec.minimum)
217		}
218	}
219	
220	func applyProgressiveStressContract(details map[string]interface{}) error {
221		var failures []string
222		totalRequests := 0
223		totalSuccess := 0
224	
225		for _, floor := range progressiveStressStageFloors {
226			stageKey := fmt.Sprintf("qps_%d", floor.qps)
227			stageDetails, err := nestedDetails(details, stageKey)
228			if err != nil {
229				failures = append(failures, err.Error())
230				continue
231			}
232	
233			rate, err := buildAcceptanceRate(stageDetails, "successful", "total_requests")
234			if err != nil {
235				failures = append(failures, fmt.Sprintf("%s: %v", stageKey, err))
236				continue
237			}
238	
239			rate.addDetails(stageDetails, "success_rate", "minimum_success_rate", floor.minimum)
240			if err := rate.requireMinimum(
241				fmt.Sprintf("%s successful requests", stageKey),
242				floor.minimum,
243			); err != nil {
244				failures = append(failures, err.Error())
245			}
246	
247			totalRequests += rate.total
248			totalSuccess += rate.passed
249		}
250	
251		overallDetails, err := ensureNestedDetails(details, "overall")
252		if err != nil {
253			return err
254		}
255	
256		overallDetails["total_requests"] = totalRequests
257		overallDetails["successful"] = totalSuccess
258		overallDetails["failed"] = totalRequests - totalSuccess
259	
260		overallRate := acceptanceRate{passed: totalSuccess, total: totalRequests}
261		overallRate.addDetails(overallDetails, "success_rate", "minimum_success_rate", minBaselineProgressiveStressOverallRate)
262		if err := overallRate.requireMinimum("overall successful requests", minBaselineProgressiveStressOverallRate); err != nil {
263			failures = append(failures, err.Error())
264		}
265	
266		if len(failures) > 0 {
267			return errors.New(strings.Join(failures, "; "))
268		}
269	
270		return nil
271	}
272	
273	type acceptanceRate struct {
274		passed int
275		total  int
276	}
277	
278	func buildAcceptanceRate(details map[string]interface{}, passedKey, totalKey string) (acceptanceRate, error) {
279		passed, err := detailInt(details, passedKey)
280		if err != nil {
281			return acceptanceRate{}, err
282		}
283	
284		total, err := detailInt(details, totalKey)
285		if err != nil {
286			return acceptanceRate{}, err
287		}
288	
289		return acceptanceRate{
290			passed: passed,
291			total:  total,
292		}, nil
293	}
294	
295	func (r acceptanceRate) percent() float64 {
296		if r.total == 0 {
297			return 0
298		}
299	
300		return float64(r.passed) / float64(r.total) * 100
301	}
302	
303	func (r acceptanceRate) addDetails(details map[string]interface{}, actualKey, minimumKey string, minimum float64) {
304		details[actualKey] = formatPercent(r.percent())
305		details[minimumKey] = formatPercent(minimum)
306	}
307	
308	func (r acceptanceRate) requireMinimum(metricName string, minimum float64) error {
309		actual := r.percent()
310		if actual < minimum {
311			return fmt.Errorf("%d/%d %s (%.2f%%) below minimum %.2f%%", r.passed, r.total, metricName, actual, minimum)
312		}
313	
314		return nil
315	}
316	
317	func nestedDetails(details map[string]interface{}, key string) (map[string]interface{}, error) {
318		value, ok := details[key]
319		if !ok {
320			return nil, fmt.Errorf("missing details[%q]", key)
321		}
322	
323		nested, ok := value.(map[string]interface{})
324		if !ok {
325			return nil, fmt.Errorf("details[%q] is %T, want map[string]interface{}", key, value)
326		}
327	
328		return nested, nil
329	}
330	
331	func ensureNestedDetails(details map[string]interface{}, key string) (map[string]interface{}, error) {
332		if value, ok := details[key]; ok {
333			nested, ok := value.(map[string]interface{})
334			if !ok {
335				return nil, fmt.Errorf("details[%q] is %T, want map[string]interface{}", key, value)
336			}
337	
338			return nested, nil
339		}
340	
341		nested := make(map[string]interface{})
342		details[key] = nested
343		return nested, nil
344	}
345	
346	func detailInt(details map[string]interface{}, key string) (int, error) {
347		value, ok := details[key]
348		if !ok {
349			return 0, fmt.Errorf("missing details[%q]", key)
350		}
351	
352		number := reflect.ValueOf(value)
353		switch number.Kind() {
354		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
355			return int(number.Int()), nil
356		case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
357			return int(number.Uint()), nil
358		case reflect.Float32, reflect.Float64:
359			return int(number.Float()), nil
360		}
361	
362		return 0, fmt.Errorf("details[%q] is %T, want integer count", key, value)
363	}
364	
365	func formatPercent(value float64) string {
366		return fmt.Sprintf("%.2f%%", value)
367	}
368

