314	// createHFTokenSecret creates a Kubernetes secret for HF_TOKEN if it's available in the environment.
315	func (r *Runner) createHFTokenSecret(ctx context.Context, kubeClient *kubernetes.Clientset) error {
316		hfToken := os.Getenv("HF_TOKEN")
317		if hfToken == "" {
318			return nil
319		}
320	
321		nsName := "vllm-semantic-router-system"
322	
323		_, err := kubeClient.CoreV1().Namespaces().Get(ctx, nsName, metav1.GetOptions{})
324		if err != nil {
325			ns := &corev1.Namespace{
326				ObjectMeta: metav1.ObjectMeta{Name: nsName},
327			}
328			_, err = kubeClient.CoreV1().Namespaces().Create(ctx, ns, metav1.CreateOptions{})
329			if err != nil && !strings.Contains(err.Error(), "already exists") {
330				r.log("⚠️  Could not create namespace %s (will be created by profile): %v", nsName, err)
331			}
332		}
333	
334		secret := &corev1.Secret{
335			ObjectMeta: metav1.ObjectMeta{
336				Name:      "hf-token-secret",
337				Namespace: nsName,
338			},
339			Type: corev1.SecretTypeOpaque,
340			StringData: map[string]string{
341				"token": hfToken,
342			},
343		}
344	
345		_, err = kubeClient.CoreV1().Secrets(nsName).Create(ctx, secret, metav1.CreateOptions{})
346		if err == nil {
347			return nil
348		}
349	
350		return r.handleHFTokenSecretCreateError(ctx, kubeClient, nsName, secret, err)
351	}
352	
353	func (r *Runner) handleHFTokenSecretCreateError(
354		ctx context.Context,
355		kubeClient *kubernetes.Clientset,
356		nsName string,
357		secret *corev1.Secret,
358		createErr error,
359	) error {
360		if strings.Contains(createErr.Error(), "already exists") {
361			_, err := kubeClient.CoreV1().Secrets(nsName).Update(ctx, secret, metav1.UpdateOptions{})
362			if err != nil {
363				return fmt.Errorf("failed to update existing HF_TOKEN secret in %s: %w", nsName, err)
364			}
365			return nil
366		}
367		if strings.Contains(createErr.Error(), "not found") {
368			r.log("⚠️  Namespace %s not found yet (will be created by profile)", nsName)
369			return nil
370		}
371		return fmt.Errorf("failed to create HF_TOKEN secret in %s: %w", nsName, createErr)
