		fmt.Sprintf("%s:%s", localPort, servicePort),
		opts.Verbose,
	)
	if err != nil {
		return nil, fmt.Errorf("failed to start port forwarding: %w", err)
	}

	time.Sleep(2 * time.Second)
	return newSession(localPort, stop), nil
}

